#nullable enable // autogenerated

using MVZ2.Vanilla.Almanacs;
using PVZEngine.Level;
using PVZEngine.Placements;

namespace MVZ2.GameContent.Placements
{
    [PlacementDefinition(VanillaPlacementNames.unsodded)]
    public class UnsoddedPlacement : PlacementDefinition
    {
        public UnsoddedPlacement(string nsp, string name) : base(nsp, name, VanillaSpawnConditions.unsodded)
        {
            AddMethod(VanillaPlaceMethods.entity);
            AddMethod(VanillaPlaceMethods.firstAid);
            this.SetAlmanacTag(VanillaAlmanacTagID.placementUnsodded);
        }
    }
}
